import textwrap
from collections import Counter
from pathlib import Path
from tempfile import NamedTemporaryFile
from typing import Dict, Iterable, List, Optional, Set, Tuple

import viktor as vkt

try:
    import ifcopenshell
    import ifcopenshell.util.element
except Exception:  # pragma: no cover
    ifcopenshell = None


def _safe_str(value) -> str:
    if value is None:
        return ""
    return str(value)


def _get_attr(obj, attr: str, default=None):
    try:
        return getattr(obj, attr)
    except Exception:
        return default


def _is_spatial_structure(obj) -> bool:
    return obj is not None and hasattr(obj, "is_a") and obj.is_a("IfcSpatialStructureElement")


def _direct_spatial_container(obj):
    """Return direct container based on IfcRelContainedInSpatialStructure (if any)."""
    # Prefer IfcOpenShell util when available.
    try:
        container = ifcopenshell.util.element.get_container(obj)
        if container is not None:
            return container
    except Exception:
        pass

    # Fallback: inverse attribute (often available on IfcProduct)
    rels = _get_attr(obj, "ContainedInStructure", []) or []
    for rel in rels:
        try:
            container = rel.RelatingStructure
            if container is not None:
                return container
        except Exception:
            continue
    return None


def _parent_objects(obj) -> List:
    """Return parent objects via decomposition / nesting (common sources of indirect containment)."""
    parents = []

    # Decomposition (IfcRelAggregates / IfcRelDecomposes)
    for rel in (_get_attr(obj, "Decomposes", []) or []):
        try:
            parent = rel.RelatingObject
            if parent is not None:
                parents.append(parent)
        except Exception:
            continue

    # Nesting (IfcRelNests)
    for rel in (_get_attr(obj, "Nests", []) or []):
        try:
            parent = rel.RelatingObject
            if parent is not None:
                parents.append(parent)
        except Exception:
            continue

    return parents


def _find_spatial_container(obj, *, check_indirect: bool, _visited: Optional[Set[int]] = None):
    """Find the (direct or indirect) spatial container of an element.

    Indirect means: element is part of another element (via Decomposes/Nests) which *is* contained in a spatial
    structure.
    """
    if obj is None:
        return None

    if _visited is None:
        _visited = set()

    try:
        oid = int(obj.id())
    except Exception:
        oid = id(obj)

    if oid in _visited:
        return None
    _visited.add(oid)

    container = _direct_spatial_container(obj)
    if container is not None:
        return container

    if not check_indirect:
        return None

    for parent in _parent_objects(obj):
        container = _find_spatial_container(parent, check_indirect=check_indirect, _visited=_visited)
        if container is not None:
            return container

    return None


def _find_storey_from_spatial(spatial_obj):
    """If spatial_obj is a storey -> return it.

    If it is e.g. IfcSpace, climb upward via Decomposes until a storey is found.
    """
    if spatial_obj is None:
        return None

    if hasattr(spatial_obj, "is_a") and spatial_obj.is_a("IfcBuildingStorey"):
        return spatial_obj

    visited: Set[int] = set()
    current = spatial_obj

    while current is not None:
        try:
            cid = int(current.id())
        except Exception:
            cid = id(current)
        if cid in visited:
            break
        visited.add(cid)

        if hasattr(current, "is_a") and current.is_a("IfcBuildingStorey"):
            return current

        decomposes = _get_attr(current, "Decomposes", []) or []
        if not decomposes:
            break

        # A spatial structure element typically has exactly one parent in the spatial hierarchy.
        next_parent = None
        for rel in decomposes:
            try:
                next_parent = rel.RelatingObject
                break
            except Exception:
                continue
        current = next_parent

    return None


def _spatial_path_names(spatial_obj, max_depth: int = 6) -> str:
    """Return a readable 'Space > Storey > Building > Site ...' style path."""
    if spatial_obj is None:
        return ""

    parts: List[str] = []
    current = spatial_obj
    visited: Set[int] = set()

    for _ in range(max_depth):
        if current is None:
            break

        try:
            cid = int(current.id())
        except Exception:
            cid = id(current)
        if cid in visited:
            break
        visited.add(cid)

        cls = _safe_str(_get_attr(current, "is_a", lambda: "")())
        name = _safe_str(_get_attr(current, "Name", ""))
        label = cls
        if name:
            label = f"{cls} ({name})"
        parts.append(label)

        decomposes = _get_attr(current, "Decomposes", []) or []
        parent = None
        for rel in decomposes:
            try:
                parent = rel.RelatingObject
                break
            except Exception:
                continue
        current = parent

    return " > ".join(parts)


def _open_ifc_model(ifc_file: vkt.File):
    if ifcopenshell is None:
        raise vkt.UserError(
            "IfcOpenShell is not available. Add 'ifcopenshell' to requirements.txt for this app."
        )

    # VIKTOR File.getvalue() returns bytes
    raw = ifc_file.getvalue()
    if not raw:
        raise vkt.UserError("The uploaded IFC file is empty.")

    with NamedTemporaryFile(suffix=".ifc", delete=False) as tmp:
        tmp.write(raw)
        tmp_path = Path(tmp.name)

    return ifcopenshell.open(tmp_path.as_posix())


class Parametrization(vkt.Parametrization):
    page = vkt.Page(
        "Spatial containment",
        views=["ifc_and_data_view", "validation_summary", "orphaned_elements"],
    )

    page.inputs = vkt.Section("Inputs")
    page.inputs.intro = vkt.Text(
        textwrap.dedent(
            """\
            # Spatial Containment Validator

            Upload an IFC file and validate that elements are part of the **spatial hierarchy**.

            **Checks**
            - *Any spatial container*: element has a spatial container (e.g. `IfcBuildingStorey`, `IfcSpace`, `IfcBuilding`).
            - *Belongs to a storey*: element can be traced to an `IfcBuildingStorey`.

            This helps find **orphaned** components that are not assigned to any storey / spatial structure.
            """
        )
    )

    page.inputs.ifc = vkt.FileField("Upload IFC (.ifc)")
    page.inputs.requirement = vkt.OptionField(
        "Requirement",
        options=["Any spatial container", "Belongs to a building storey"],
        default="Belongs to a building storey",
        variant="radio",
    )
    page.inputs.check_indirect = vkt.BooleanField(
        "Consider indirect containment via parent elements (decomposition / nesting)",
        default=True,
    )
    page.inputs.include_proxies = vkt.BooleanField(
        "Include IfcBuildingElementProxy", default=True
    )
    page.inputs.geometry = vkt.GeometrySelectField(
        "Select an element in the IFC viewer (optional)"
    )


class Controller(vkt.Controller):
    label = "Spatial Containment Validator"
    parametrization = Parametrization(width=60)

    def _require_ifc_file(self, params) -> vkt.File:
        if not params.page.inputs.ifc:
            raise vkt.UserError("Upload an IFC file to start the validation.")
        if not params.page.inputs.ifc.file:
            raise vkt.UserError("Upload an IFC file to start the validation.")
        return params.page.inputs.ifc.file

    def _iter_elements_to_check(self, model, include_proxies: bool) -> Iterable:
        # IfcElement covers most building elements. We intentionally do NOT include IfcSpatialStructureElement.
        elements = model.by_type("IfcElement") or []
        for el in elements:
            if not include_proxies and hasattr(el, "is_a") and el.is_a("IfcBuildingElementProxy"):
                continue
            yield el

    def _validate(self, params) -> Tuple[List[Dict], Dict[str, int]]:
        """Returns (noncompliant_rows, metrics)."""
        ifc_file = self._require_ifc_file(params)
        model = _open_ifc_model(ifc_file)

        requirement = params.page.inputs.requirement
        check_indirect = bool(params.page.inputs.check_indirect)
        include_proxies = bool(params.page.inputs.include_proxies)

        noncompliant: List[Dict] = []
        total = 0
        orphan_count = 0
        not_in_storey_count = 0
        by_class = Counter()

        for el in self._iter_elements_to_check(model, include_proxies=include_proxies):
            total += 1
            by_class[el.is_a()] += 1

            spatial = _find_spatial_container(el, check_indirect=check_indirect)
            storey = _find_storey_from_spatial(spatial) if spatial is not None else None

            is_orphan = spatial is None or not _is_spatial_structure(spatial)
            fails_storey = storey is None

            if requirement == "Any spatial container":
                non_ok = is_orphan
                reason = "No spatial container found" if is_orphan else ""
            else:
                # Belongs to a building storey
                non_ok = fails_storey
                if spatial is None:
                    reason = "No spatial container found"
                else:
                    reason = f"Contained in {spatial.is_a()} but no IfcBuildingStorey found in spatial chain"

            if non_ok:
                if is_orphan:
                    orphan_count += 1
                if fails_storey:
                    not_in_storey_count += 1

                direct_container = _direct_spatial_container(el)
                direct_container_label = ""
                if direct_container is not None and hasattr(direct_container, "is_a"):
                    direct_container_label = f"{direct_container.is_a()} ({_safe_str(_get_attr(direct_container, 'Name', ''))})"

                parents = _parent_objects(el)
                parent_label = ""
                if parents:
                    p0 = parents[0]
                    if hasattr(p0, "is_a"):
                        parent_label = f"{p0.is_a()} ({_safe_str(_get_attr(p0, 'Name', ''))})"

                storey_label = ""
                if storey is not None:
                    elev = _get_attr(storey, "Elevation", None)
                    elev_txt = f", Elev={elev}" if elev is not None else ""
                    storey_label = f"{_safe_str(_get_attr(storey, 'Name', ''))}{elev_txt}"

                noncompliant.append(
                    {
                        "ifc_id": int(el.id()),
                        "global_id": _safe_str(_get_attr(el, "GlobalId", "")),
                        "ifc_class": _safe_str(el.is_a()),
                        "name": _safe_str(_get_attr(el, "Name", "")),
                        "reason": reason,
                        "direct_container": direct_container_label,
                        "resolved_container_path": _spatial_path_names(spatial),
                        "resolved_storey": storey_label,
                        "parent": parent_label,
                    }
                )

        metrics = {
            "total": total,
            "noncompliant": len(noncompliant),
            "orphans": orphan_count,
            "not_in_storey": not_in_storey_count,
        }

        # Add top element classes to metrics for display (keep it small)
        for cls, cnt in by_class.most_common(8):
            metrics[f"cls_{cls}"] = cnt

        return noncompliant, metrics

    @vkt.IFCAndDataView("IFC viewer + element inspector", x_axis_to_right=True)
    def ifc_and_data_view(self, params, **kwargs):
        ifc_file = self._require_ifc_file(params)
        model = _open_ifc_model(ifc_file)

        selected = params.page.inputs.geometry
        if not selected:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "Tip",
                    "Select an element in the viewer to inspect spatial containment.",
                    status=vkt.DataStatus.INFO,
                )
            )
            return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

        try:
            element = model.by_id(int(selected))
        except Exception:
            element = None

        if element is None:
            data = vkt.DataGroup(
                vkt.DataItem(
                    "Selection",
                    "Could not resolve the selected IFC id.",
                    status=vkt.DataStatus.ERROR,
                )
            )
            return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

        check_indirect = bool(params.page.inputs.check_indirect)
        spatial = _find_spatial_container(element, check_indirect=check_indirect)
        storey = _find_storey_from_spatial(spatial) if spatial is not None else None

        orphan = spatial is None
        storey_missing = storey is None

        status = vkt.DataStatus.SUCCESS
        msg = ""
        if orphan:
            status = vkt.DataStatus.ERROR
            msg = "This element is not contained in the spatial structure."
        elif storey_missing:
            status = vkt.DataStatus.WARNING
            msg = "This element is contained, but not in a building storey."

        data = vkt.DataGroup(
            vkt.DataItem("IFC id", int(element.id())),
            vkt.DataItem("GlobalId", _safe_str(_get_attr(element, "GlobalId", ""))),
            vkt.DataItem("Class", _safe_str(element.is_a())),
            vkt.DataItem("Name", _safe_str(_get_attr(element, "Name", ""))),
            vkt.DataItem(
                "Containment status",
                "OK" if status == vkt.DataStatus.SUCCESS else "Check",
                status=status,
                status_message=msg,
            ),
            vkt.DataItem("Resolved spatial container", _safe_str(getattr(spatial, "is_a", lambda: "")() if spatial else "")),
            vkt.DataItem("Spatial path", _spatial_path_names(spatial) if spatial else ""),
            vkt.DataItem(
                "Resolved storey",
                _safe_str(_get_attr(storey, "Name", "")) if storey else "",
            ),
        )

        return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

    @vkt.DataView("Validation summary")
    def validation_summary(self, params, **kwargs):
        try:
            noncompliant, metrics = self._validate(params)
        except vkt.UserError as e:
            return vkt.DataResult(vkt.DataGroup(vkt.DataItem("Input", str(e), status=vkt.DataStatus.INFO)))

        total = metrics["total"]
        n_bad = metrics["noncompliant"]
        n_orphan = metrics["orphans"]
        n_not_in_storey = metrics["not_in_storey"]

        if n_bad == 0:
            overall_status = vkt.DataStatus.SUCCESS
            overall_msg = "All checked elements comply with the selected requirement."
        else:
            overall_status = vkt.DataStatus.WARNING
            overall_msg = "Noncompliant elements found. See the table view."

        top_classes = []
        for k, v in metrics.items():
            if k.startswith("cls_"):
                top_classes.append(vkt.DataItem(k.replace("cls_", ""), v))

        data = vkt.DataGroup(
            vkt.DataItem(
                "Overall",
                "OK" if overall_status == vkt.DataStatus.SUCCESS else "Attention",
                status=overall_status,
                status_message=overall_msg,
            ),
            vkt.DataItem("Checked IfcElement count", total),
            vkt.DataItem("Noncompliant count", n_bad),
            vkt.DataItem("Orphaned (no spatial container)", n_orphan),
            vkt.DataItem("Not in any storey", n_not_in_storey),
            vkt.DataItem("Top IFC classes", "", subgroup=vkt.DataGroup(*top_classes))
            if top_classes
            else vkt.DataItem("Top IFC classes", ""),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Noncompliant elements")
    def orphaned_elements(self, params, **kwargs):
        try:
            noncompliant, _ = self._validate(params)
        except vkt.UserError:
            return vkt.TableResult([], column_headers=[
                "IFC id",
                "GlobalId",
                "IFC Class",
                "Name",
                "Reason",
                "Direct container",
                "Resolved container path",
                "Resolved storey",
                "Parent element",
            ])

        rows = []
        for r in noncompliant:
            rows.append(
                [
                    r["ifc_id"],
                    r["global_id"],
                    r["ifc_class"],
                    r["name"],
                    r["reason"],
                    r["direct_container"],
                    r["resolved_container_path"],
                    r["resolved_storey"],
                    r["parent"],
                ]
            )

        return vkt.TableResult(
            rows,
            column_headers=[
                "IFC id",
                "GlobalId",
                "IFC Class",
                "Name",
                "Reason",
                "Direct container",
                "Resolved container path",
                "Resolved storey",
                "Parent element",
            ],
        )
